type Match =
  | { kind: "found"; params: Record<string, string> }
  | { kind: "wrong-method"; allowed: string[] }
  | { kind: "not-found" };

const routes = [
  { method: "GET", parts: ["books"] },
  { method: "POST", parts: ["books"] },
  { method: "GET", parts: ["books", ":id"] },
];

function match(method: string, path: string): Match {
  const parts = path.split("/").filter((part) => part !== "");
  const allowed: string[] = [];
  for (const route of routes) {
    if (route.parts.length !== parts.length) continue;
    const params: Record<string, string> = {};
    let ok = true;
    for (const [i, want] of route.parts.entries()) {
      if (want.startsWith(":")) params[want.slice(1)] = parts[i]!;
      else if (want !== parts[i]) ok = false;
    }
    if (!ok) continue;
    if (route.method === method) return { kind: "found", params };
    allowed.push(route.method);
  }
  return allowed.length > 0 ? { kind: "wrong-method", allowed } : { kind: "not-found" };
}

