  | { readonly kind: "found"; readonly params: Record<string, string> }
  | { readonly kind: "wrong-method"; readonly allowed: readonly string[] }
  | { readonly kind: "not-found" };

function splitPath(path: string): string[] {
  return path.split("/").filter((part) => part !== "");
}

function matchParts(pattern: readonly string[], parts: readonly string[]): Record<string, string> | undefined {
  if (pattern.length !== parts.length) return undefined;
  const params: Record<string, string> = {};
  for (const [i, want] of pattern.entries()) {
    if (want.startsWith(":")) params[want.slice(1)] = parts[i]!;
    else if (want !== parts[i]) return undefined;
  }
  return params;
}

class Router {
  private readonly routes: { method: string; parts: string[] }[] = [];
  add(method: string, pattern: string): this {
    this.routes.push({ method, parts: splitPath(pattern) });
    return this;
  }
  match(method: string, path: string): Match {
    const parts = splitPath(path);
    const allowed: string[] = [];
    for (const route of this.routes) {
      const params = matchParts(route.parts, parts);
      if (params === undefined) continue;
      if (route.method === method) return { kind: "found", params };
      allowed.push(route.method);
    }
    return allowed.length > 0 ? { kind: "wrong-method", allowed } : { kind: "not-found" };
  }
